/**
 * Directed blocker links: `issueId` is blocked by `blockerId`.
 */
import { and, asc, eq } from "drizzle-orm";
import { getDb, issueDependencies, issues } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Issue, IssueDependency } from "@/types/issue";
import { toIssue, brandId, brandStamp } from "./_mappers";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact } from "./_paging";

function toDependency(row: typeof issueDependencies.$inferSelect): IssueDependency {
  return {
    orgId: brandId<OrgId>(row.orgId),
    issueId: brandId<IssueId>(row.issueId),
    blockerId: brandId<IssueId>(row.blockerId),
    createdBy: brandId<UserId>(row.createdBy),
    createdAt: brandStamp(row.createdAt),
  };
}

export async function findDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<IssueDependency | null> {
  const row = getDb()
    .select()
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .get();
  return row ? toDependency(row) : null;
}

export async function insertDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
  createdBy: UserId,
): Promise<IssueDependency> {
  const row = getDb()
    .insert(issueDependencies)
    .values({
      orgId,
      issueId,
      blockerId,
      createdBy,
      createdAt: toIsoTimestamp(new Date()),
    })
    .returning()
    .get();
  return toDependency(row);
}

/** Resolves `true` when a row was deleted. */
export async function deleteDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<boolean> {
  const existing = await findDependency(orgId, issueId, blockerId);
  if (!existing) return false;
  getDb()
    .delete(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .run();
  return true;
}

export async function listLinksForOrg(
  orgId: OrgId,
): Promise<readonly IssueDependency[]> {
  const rows = getDb()
    .select()
    .from(issueDependencies)
    .where(orgPredicate(issueDependencies.orgId, orgId))
    .all();
  return rows.map(toDependency);
}

/** Blocker issues of `issueId` that are not archived, issue number ascending. */
export async function listBlockerIssues(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select({ issue: issues })
    .from(issueDependencies)
    .innerJoin(
      issues,
      and(
        eq(issues.id, issueDependencies.blockerId),
        eq(issues.orgId, issueDependencies.orgId),
      ),
    )
    .where(
      and(
        ...compact(
          orgPredicate(issueDependencies.orgId, orgId),
          eq(issueDependencies.issueId, issueId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(asc(issues.number))
    .all();
  return rows.map((row) => toIssue(row.issue));
}

/** Issues that list `blockerId` as a blocker, including archived and closed. */
export async function listDependentIssues(
  orgId: OrgId,
  blockerId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select({ issue: issues })
    .from(issueDependencies)
    .innerJoin(
      issues,
      and(
        eq(issues.id, issueDependencies.issueId),
        eq(issues.orgId, issueDependencies.orgId),
      ),
    )
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .all();
  return rows.map((row) => toIssue(row.issue));
}

/**
 * Blocked-by links between issues, the completion gate, and the unblocked notification.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, emit subscribers via registerIssueDependencyListeners, notify
 */
import { subscribe } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import type { IssueId, OrgId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Issue, IssueDependency, IssueStatus } from "@/types/issue";
import type { Actor } from "@/types/member";
import { issueResource, requireFound } from "./_support";
import { notify } from "./notification-service";

export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly blockerIds: readonly IssueId[]) {
    super(`Issue is blocked by ${blockerIds.join(", ")}`);
    this.name = "IssueBlockedError";
  }
}

function isClosedStatus(status: IssueStatus): boolean {
  return (CLOSED_ISSUE_STATUSES as readonly IssueStatus[]).includes(status);
}

/** A blocker is open while it is not archived and not done or canceled. */
export function isOpenBlocker(issue: Issue): boolean {
  return issue.archivedAt === null && !isClosedStatus(issue.status);
}

function createsCycle(
  links: readonly IssueDependency[],
  issueId: IssueId,
  blockerId: IssueId,
): boolean {
  const blockersOf = new Map<string, string[]>();
  for (const link of links) {
    const next = blockersOf.get(link.issueId) ?? [];
    next.push(link.blockerId);
    blockersOf.set(link.issueId, next);
  }

  const seen = new Set<string>();
  const stack = [blockerId];
  while (stack.length > 0) {
    const current = stack.pop();
    if (current === undefined || seen.has(current)) continue;
    if (current === issueId) return true;
    seen.add(current);
    for (const next of blockersOf.get(current) ?? []) stack.push(next);
  }
  return false;
}

/**
 * Records that `issueId` is blocked by `blockerId`. An existing link is returned as-is.
 */
export async function addBlocker(
  actor: Actor,
  input: { orgId: OrgId; issueId: IssueId; blockerId: IssueId },
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  const blocker = requireFound(
    await issueRepo.findIssueById(input.orgId, input.blockerId),
    "Issue",
    input.blockerId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);
  assertNotArchived("Issue", blocker.id, blocker);

  if (input.issueId === input.blockerId) {
    throw new Error("An issue cannot block itself");
  }

  const existing = await dependencyRepo.findDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
  if (existing) return existing;

  const links = await dependencyRepo.listLinksForOrg(input.orgId);
  if (createsCycle(links, input.issueId, input.blockerId)) {
    throw new Error("Issue dependency would create a cycle");
  }

  return dependencyRepo.insertDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
    actor.userId,
  );
}

/** Deletes the link. `true` when a row was removed. */
export async function removeBlocker(
  actor: Actor,
  input: { orgId: OrgId; issueId: IssueId; blockerId: IssueId },
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  return dependencyRepo.deleteDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
}

/** Non-archived blockers of `issueId`, ordered by issue number ascending. */
export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return dependencyRepo.listBlockerIssues(orgId, issueId);
}

/** Rejects a transition to `done` while any blocker is still open. */
export async function assertCanComplete(
  orgId: OrgId,
  issueId: IssueId,
): Promise<void> {
  const blockers = await dependencyRepo.listBlockerIssues(orgId, issueId);
  const openIds = blockers.filter(isOpenBlocker).map((issue) => issue.id);
  if (openIds.length > 0) throw new IssueBlockedError(openIds);
}

async function notifyUnblocked(
  orgId: OrgId,
  blockerId: IssueId,
  actorId: Actor["userId"] | null,
): Promise<void> {
  const dependents = await dependencyRepo.listDependentIssues(orgId, blockerId);
  for (const issue of dependents) {
    if (issue.archivedAt !== null) continue;
    if (isClosedStatus(issue.status)) continue;
    if (issue.assigneeId === null) continue;

    const blockers = await dependencyRepo.listBlockerIssues(orgId, issue.id);
    if (blockers.some(isOpenBlocker)) continue;

    await notify(orgId, "issue_unblocked", [issue.assigneeId], {
      title: "Issue unblocked",
      body: `${issue.title} is no longer blocked`,
