function createsCycle(
  links: readonly IssueDependency[],
  issueId: IssueId,
  blockerId: IssueId,
): boolean {
  const blockersOf = new Map<string, string[]>();
  for (const link of links) {
    const next = blockersOf.get(link.issueId) ?? [];
    next.push(link.blockerId);
    blockersOf.set(link.issueId, next);
  }

  const seen = new Set<string>();
  const stack = [blockerId];
  while (stack.length > 0) {
    const current = stack.pop();
    if (current === undefined || seen.has(current)) continue;
    if (current === issueId) return true;
    seen.add(current);
    for (const next of blockersOf.get(current) ?? []) stack.push(next);
